  fun ms' => exists (a1' a2' t5' t6' : word) (F' : bvmap 5 word) (fc' : bv 32),
    ms' = MS (mkR ra sp gp tp t0 t1 (Z_to_bv 64 0) s0 s1 a0 a1' a2' a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
