    (MS (mkR (Z_to_bv 64 11) sp gp tp t0 t1 (Z_to_bv 64 (21 - kk)) s0 (Z_to_bv 64 (hp_S1 p)) a0 a1 a2 a3 (Z_to_bv 64 (hp_wpl p * 4)) a5 a6 a7
