(* [comment removed for export] *)
Definition vp_join (p : hpp) (DD wpld i j : Z) (sp gp tp s0 : word) (F : bvmap 5 word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (a1' a2' t2' t3' t4' t5' t6' : word) (F' : bvmap 5 word) (fc' : bv 32),
    ms' = MS (mkR (Z_to_bv 64 11) sp gp tp (Z_to_bv 64 (hp_LT p i)) (Z_to_bv 64 (vp_CP p i j)) t2' s0 (Z_to_bv 64 (hp_S1 p))
                  (Z_to_bv 64 wpld) a1' a2' (Z_to_bv 64 i) (Z_to_bv 64 (hp_wpl p * 4)) (Z_to_bv 64 (vp_CP p i 0)) (Z_to_bv 64 j) (Z_to_bv 64 (vp_lined DD wpld i))
                  (Z_to_bv 64 (hp_RR p)) (Z_to_bv 64 (-10)) (Z_to_bv 64 (hp_h p)) (Z_to_bv 64 21) (Z_to_bv 64 65296) (Z_to_bv 64 2147450880)
                  (Z_to_bv 64 (hp_c p)) (Z_to_bv 64 (hp_w p)) (Z_to_bv 64 10) (Z_to_bv 64 (hp_SP p)) t3' t4' t5' t6')
             F' (Z_to_bv 64 0xc323c) fc' None m (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc'.

(* [comment removed for export] *)
Definition vp_j_exit (p : hpp) (DD ND wpld i : Z) (sp gp tp s0 : word) (F : bvmap 5 word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (a1' a2' t2' t3' t4' t5' t6' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem),
    ms' = MS (mkR (Z_to_bv 64 11) sp gp tp (Z_to_bv 64 (hp_LT p i)) (Z_to_bv 64 (vp_CP p i (hp_w p))) t2' s0 (Z_to_bv 64 (hp_S1 p))
                  (Z_to_bv 64 wpld) a1' a2' (Z_to_bv 64 i) (Z_to_bv 64 (hp_wpl p * 4)) (Z_to_bv 64 (vp_CP p i 0)) (Z_to_bv 64 (hp_w p)) (Z_to_bv 64 (vp_lined DD wpld i))
                  (Z_to_bv 64 (hp_RR p)) (Z_to_bv 64 (-10)) (Z_to_bv 64 (hp_h p)) (Z_to_bv 64 21) (Z_to_bv 64 65296) (Z_to_bv 64 2147450880)
                  (Z_to_bv 64 (hp_c p)) (Z_to_bv 64 (hp_w p)) (Z_to_bv 64 10) (Z_to_bv 64 (hp_SP p)) t3' t4' t5' t6')
             F' (Z_to_bv 64 0xc30e8) fc' None m' (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc' /\ munch [(DD, DD + ND)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma vp_j_loop : forall (n : nat) (p : hpp) (DD ND wpld i j : Z)
    (sp gp tp t2 s0 a1 a2 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = hp_w p - j -> 0 <= j -> (1 <= n)%nat -> 0 <= i < hp_h p -> hp_ok p -> vp_ok p DD ND wpld -> frm0 fc ->
  (forall m', munch [(DD, DD + ND)] m m' -> wmono asegs m m' -> vp_ro p DD wpld m') ->
  wr_at asegs m DD ND -> acc asegs m DD ND -> mem_inv asegs m ->
  evt asegs (vp_j_exit p DD ND wpld i sp gp tp s0 F m)
    (MS (mkR (Z_to_bv 64 11) sp gp tp (Z_to_bv 64 (hp_LT p i)) (Z_to_bv 64 (vp_CP p i j)) t2 s0 (Z_to_bv 64 (hp_S1 p))
             (Z_to_bv 64 wpld) a1 a2 (Z_to_bv 64 i) (Z_to_bv 64 (hp_wpl p * 4)) (Z_to_bv 64 (vp_CP p i 0)) (Z_to_bv 64 j) (Z_to_bv 64 (vp_lined DD wpld i))
             (Z_to_bv 64 (hp_RR p)) (Z_to_bv 64 (-10)) (Z_to_bv 64 (hp_h p)) (Z_to_bv 64 21) (Z_to_bv 64 65296) (Z_to_bv 64 2147450880)
             (Z_to_bv 64 (hp_c p)) (Z_to_bv 64 (hp_w p)) (Z_to_bv 64 10) (Z_to_bv 64 (hp_SP p)) t3 t4 t5 t6)
